import{_ as a,a0 as e,w as l,s as p,I as r,x as t,a1 as i,A as o,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"UNIX 家族小史 | LCTT x X-CMD","titleTemplate":false,"description":"UNIX 家族小史 | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"UNIX 家族小史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"UNIX 家族小史 | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151012 The Brief History Of Aix HP-UX Solaris BSD And LINUX","title":"UNIX 家族小史","tag":"201512","desc":""},"relativePath":"201512/20151012 The Brief History Of Aix HP-UX Solaris BSD And LINUX.md","filePath":"[post].md"}'),g={name:"201512/20151012 The Brief History Of Aix HP-UX Solaris BSD And LINUX.md"};function x(S,n,X,d,m,U){const s=e("Link");return l(),p("div",null,[n[22]||(n[22]=r("h1",{id:"unix-家族小史",tabindex:"-1"},[t("UNIX 家族小史 "),r("a",{class:"header-anchor",href:"#unix-家族小史","aria-label":"Permalink to “UNIX 家族小史”"},"​")],-1)),n[23]||(n[23]=r("p",null,[r("img",{src:"http://1426826955.rsc.cdn77.org/wp-content/uploads/2015/05/linux-712x445.png",alt:""})],-1)),r("p",null,[n[2]||(n[2]=t("要記住，當一扇門在你面前關閉的時候，另一扇門就會打開。肯·湯普森（",-1)),i(s,{href:"http://www.unixmen.com/ken-thompson-unix-systems-father/"},{default:o(()=>[...n[0]||(n[0]=[t("Ken Thompson",-1)])]),_:1}),n[3]||(n[3]=t("） 和丹尼斯·裏奇（",-1)),i(s,{href:"http://www.unixmen.com/dennis-m-ritchie-father-c-programming-language/"},{default:o(()=>[...n[1]||(n[1]=[t("Dennis Richie",-1)])]),_:1}),n[4]||(n[4]=t("） 兩個人就是這句名言很好的實例。他們倆是",-1)),n[5]||(n[5]=r("strong",null,"20世紀",-1)),n[6]||(n[6]=t("最優秀的信息技術專家之二，因為他們創造了最具影響力和創新性的軟件之一： ",-1)),n[7]||(n[7]=r("strong",null,"UNIX",-1)),n[8]||(n[8]=t("。",-1))]),n[24]||(n[24]=u('<h3 id="unix-系統誕生於貝爾實驗室" tabindex="-1">UNIX 系統誕生於貝爾實驗室 <a class="header-anchor" href="#unix-系統誕生於貝爾實驗室" aria-label="Permalink to “UNIX 系統誕生於貝爾實驗室”">​</a></h3><p><strong>UNIX</strong> 最開始的名字是 <strong>UNICS</strong> (<strong>UN</strong>iplexed <strong>I</strong>nformation and <strong>C</strong>omputing <strong>S</strong>ervice)，它有一個大家庭，並不是從石頭縫裏蹦出來的。UNIX的祖父是 <strong>CTSS</strong> (<strong>C</strong>ompatible <strong>T</strong>ime <strong>S</strong>haring <strong>S</strong>ystem)，它的父親是 <strong>Multics</strong> (<strong>MULT</strong>iplexed <strong>I</strong>nformation and <strong>C</strong>omputing <strong>S</strong>ervice)，這個系統能支持大量用户通過交互式分時（timesharing）的方式使用大型機。</p><p>UNIX 誕生於 <strong>1969</strong> 年，由<strong>肯·湯普森</strong>以及後來加入的<strong>丹尼斯·裏奇</strong>共同完成。這兩位優秀的研究員和科學家在一個<strong>通用電器 GE</strong>和<strong>麻省理工學院</strong>的合作項目裏工作，項目目標是開發一個叫 Multics 的交互式分時系統。</p><p>Multics 的目標是整合分時技術以及當時其他先進技術，允許用户在遠程終端通過電話（撥號）登錄到主機，然後可以編輯文檔，閲讀電子郵件，運行計算器，等等。</p><p>在之後的五年裏，AT&amp;T 公司為 Multics 項目投入了數百萬美元。他們購買了 GE-645 大型機，聚集了貝爾實驗室的頂級研究人員，例如肯·湯普森、 Stuart Feldman、丹尼斯·裏奇、道格拉斯·麥克羅伊（M. Douglas McIlroy）、 Joseph F. Ossanna 以及 Robert Morris。但是項目目標太過激進，進度嚴重滯後。最後，AT&amp;T 高層決定放棄這個項目。</p><p>貝爾實驗室的管理層決定停止這個讓許多研究人員無比糾結的操作系統上的所有遺留工作。不過要感謝湯普森，裏奇和一些其他研究員，他們把老闆的命令丟到一邊，並繼續在實驗室裏滿懷熱心地忘我工作，最終孵化出前無古人後無來者的 UNIX。</p><p>UNIX 的第一聲啼哭是在一台 PDP-7 微型機上，它是湯普森測試自己在操作系統設計上的點子的機器，也是湯普森和 裏奇一起玩 Space and Travel 遊戲的模擬器。</p><blockquote><p>“我們想要的不僅是一個優秀的編程環境，而是能圍繞這個系統形成團體。按我們自己的經驗，通過遠程訪問和分時主機實現的公共計算，本質上不只是用終端輸入程序代替打孔機而已，而是鼓勵密切溝通。”丹尼斯·裏奇説。</p></blockquote><p>UNIX 是第一個靠近理想的系統，在這裏程序員可以坐在機器前自由擺弄程序，探索各種可能性並隨手測試。在 UNIX 整個生命週期裏，它吸引了大量因其他操作系統限制而投身過來的高手做出無私貢獻，因此它的功能模型一直保持上升趨勢。</p><p>UNIX 在 1970 年因為 PDP-11/20 獲得了首次資金注入，之後正式更名為 UNIX 並支持在 PDP-11/20 上運行。UNIX 帶來的第一次用於實際場景中是在 1971 年，貝爾實驗室的專利部門配備來做文字處理。</p><h3 id="unix-上的-c-語言革命" tabindex="-1">UNIX 上的 C 語言革命 <a class="header-anchor" href="#unix-上的-c-語言革命" aria-label="Permalink to “UNIX 上的 C 語言革命”">​</a></h3><p>丹尼斯·裏奇在 1972 年發明了一種叫 “<strong>C</strong>” 的高級編程語言 ，之後他和肯·湯普森決定用 “C” 重寫 UNIX 系統，來支持更好的移植性。他們在那一年裏編寫和調試了差不多 100,000 行代碼。在遷移到 “C” 語言後，系統可移植性非常好，只需要修改一小部分機器相關的代碼就可以將 UNIX 移植到其他計算機平台上。</p><p>UNIX 第一次公開露面是 1973 年丹尼斯·裏奇和肯·湯普森在操作系統原理（Operating Systems Principles）上發表的一篇論文，然後 AT&amp;T 發佈了 UNIX 系統第 5 版，並授權給教育機構使用，之後在 1975 年第一次以 <strong>$20.000</strong> 的價格授權企業使用 UNIX 第 6 版。應用最廣泛的是 1980 年發佈的 UNIX 第 7 版，任何人都可以購買授權，只是授權條款非常嚴格。授權內容包括源代碼，以及用 PDP-11 彙編語言寫的及其相關內核。反正，各種版本 UNIX 系統完全由它的用户手冊確定。</p><h3 id="aix-系統" tabindex="-1">AIX 系統 <a class="header-anchor" href="#aix-系統" aria-label="Permalink to “AIX 系統”">​</a></h3><p>在 <strong>1983</strong> 年，<strong>微軟</strong>計劃開發 <strong>Xenix</strong> 作為 MS-DOS 的多用户版繼任者，他們在那一年花了 $8,000 搭建了一台擁有 <strong>512 KB</strong> 內存以及 <strong>10 MB</strong>硬盤並運行 Xenix 的 Altos 586。而到 1984 年為止，全世界 UNIX System V 第二版的安裝數量已經超過了 100,000 。在 1986 年發佈了包含因特網域名服務的 4.3BSD，而且 <strong>IBM</strong> 宣佈 <strong>AIX 系統</strong>的安裝數已經超過 250,000。AIX 基於 Unix System V 開發，這套系統擁有 BSD 風格的根文件系統，是兩者的結合。</p><p>AIX 第一次引入了 <strong>日誌文件系統 (JFS)</strong> 以及集成邏輯卷管理器 (Logical Volume Manager ，LVM)。IBM 在 1989 年將 AIX 移植到自己的 RS/6000 平台。2001 年發佈的 5L 版是一個突破性的版本，提供了 Linux 友好性以及支持 Power4 服務器的邏輯分區。</p><p>在 2004 年發佈的 AIX 5.3 引入了支持高級電源虛擬化（ Advanced Power Virtualization，APV）的虛擬化技術，支持對稱多線程、微分區，以及共享處理器池。</p><p>在 2007 年，IBM 同時發佈 AIX 6.1 和 Power6 架構，開始加強自己的虛擬化產品。他們還將高級電源虛擬化重新包裝成 PowerVM。</p><p>這次改進包括被稱為 WPARs 的負載分區形式，類似於 Solaris 的 zones/Containers，但是功能更強。</p><h3 id="hp-ux-系統" tabindex="-1">HP-UX 系統 <a class="header-anchor" href="#hp-ux-系統" aria-label="Permalink to “HP-UX 系統”">​</a></h3><p><strong>惠普 UNIX (Hewlett-Packard’s UNIX，HP-UX)</strong> 源於 System V 第 3 版。這套系統一開始只支持 PA-RISC HP 9000 平台。HP-UX 第 1 版發佈於 1984 年。</p><p>HP-UX 第 9 版引入了 SAM，一個基於字符的圖形用户界面 (GUI)，用户可以用來管理整個系統。在 1995 年發佈的第 10 版，調整了系統文件分佈以及目錄結構，變得有點類似 AT&amp;T SVR4。</p><p>第 11 版發佈於 1997 年。這是 HP 第一個支持 64 位尋址的版本。不過在 2000 年重新發布成 11i，因為 HP 為特定的信息技術用途，引入了操作環境（operating environments）和分級應用（layered applications）的捆綁組（bundled groups）。</p><p>在 2001 年發佈的 11.20 版宣稱支持安騰（Itanium）系統。HP-UX 是第一個使用 ACLs（訪問控制列表，Access Control Lists）管理文件權限的 UNIX 系統，也是首先支持內建邏輯卷管理器（Logical Volume Manager）的系統之一。</p><p>如今，HP-UX 因為 HP 和 Veritas 的合作關係使用了 Veritas 作為主文件系統。</p><p>HP-UX 目前的最新版本是 11iv3, update 4。</p><h3 id="solaris-系統" tabindex="-1">Solaris 系統 <a class="header-anchor" href="#solaris-系統" aria-label="Permalink to “Solaris 系統”">​</a></h3><p>Sun 的 UNIX 版本是 <strong>Solaris</strong>，用來接替 1992 年創建的 <strong>SunOS</strong>。SunOS 一開始基於 BSD（伯克利軟件發行版，Berkeley Software Distribution）風格的 UNIX，但是 SunOS 5.0 版以及之後的版本都是基於重新包裝為 Solaris 的 Unix System V 第 4 版。</p><p>SunOS 1.0 版於 1983 年發佈，用於支持 Sun-1 和 Sun-2 平台。隨後在 1985 年發佈了 2.0 版。在 1987 年，Sun 和 AT&amp;T 宣佈合作一個項目以 SVR4 為基礎將 System V 和 BSD 合併成一個版本。</p><p>Solaris 2.4 是 Sun 發佈的第一個 Sparc/x86 版本。1994 年 11 月份發佈的 SunOS 4.1.4 版是最後一個版本。Solaris 7 是首個 64 位 Ultra Sparc 版本，加入了對文件系統元數據記錄的原生支持。</p><p>Solaris 9 發佈於 2002 年，支持 Linux 特性以及 Solaris 卷管理器（Solaris Volume Manager）。之後，2005 年發佈了 Solaris 10，帶來許多創新，比如支持 Solaris Containers，新的 ZFS 文件系統，以及邏輯域（Logical Domains）。</p><p>目前 Solaris 最新的版本是 第 10 版，最後的更新發佈於 2008 年。</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to “Linux”">​</a></h3><p>到了 1991 年，用來替代商業操作系統的自由（free）操作系統的需求日漸高漲。因此，<strong>Linus Torvalds</strong> 開始構建一個自由的操作系統，最終成為 <strong>Linux</strong>。Linux 最開始只有一些 “C” 文件，並且使用了阻止商業發行的授權。Linux 是一個類 UNIX 系統但又不盡相同。</p><p>2015 年發佈了基於 GNU Public License （GPL）授權的 3.18 版。IBM 聲稱有超過 1800 萬行開源代碼開源給開發者。</p><p>如今 GNU Public License 是應用最廣泛的自由軟件授權方式。根據開源軟件原則，這份授權允許個人和企業自由分發、運行、通過拷貝共享、學習，以及修改軟件源碼。</p><h3 id="unix-vs-linux-技術概要" tabindex="-1">UNIX vs. Linux：技術概要 <a class="header-anchor" href="#unix-vs-linux-技術概要" aria-label="Permalink to “UNIX vs. Linux：技術概要”">​</a></h3><ul><li>Linux 鼓勵多樣性，Linux 的開發人員來自各種背景，有更多不同經驗和意見。</li><li>Linux 比 UNIX 支持更多的平台和架構。</li><li>UNIX 商業版本的開發人員針對特定目標平台以及用户設計他們的操作系統。</li><li><strong>Linux 比 UNIX 有更好的安全性</strong>，更少受病毒或惡意軟件攻擊。截止到現在，Linux 上大約有 60-100 種病毒，但是沒有任何一種還在傳播。另一方面，UNIX 上大約有 85-120 種病毒，但是其中有一些還在傳播中。</li><li>由於 UNIX 命令、工具和元素很少改變，甚至很多接口和命令列參數在後續 UNIX 版本中一直沿用。</li><li>有些 Linux 開發項目以自願為基礎進行資助，比如 Debian。其他項目會維護一個和商業 Linux 的社區版，比如 SUSE 的 openSUSE 以及紅帽的 Fedora。</li><li>傳統 UNIX 是縱向擴展，而另一方面 Linux 是橫向擴展。</li></ul><hr>',39)),r("p",null,[n[10]||(n[10]=t("via: ",-1)),i(s,{href:"http://www.unixmen.com/brief-history-aix-hp-ux-solaris-bsd-linux/"},{default:o(()=>[...n[9]||(n[9]=[t("http://www.unixmen.com/brief-history-aix-hp-ux-solaris-bsd-linux/",-1)])]),_:1})]),r("p",null,[n[14]||(n[14]=t("作者：",-1)),i(s,{href:"http://www.unixmen.com/author/pirat9/"},{default:o(()=>[...n[11]||(n[11]=[t("M.el Khamlichi",-1)])]),_:1}),n[15]||(n[15]=t(" 譯者：",-1)),i(s,{href:"https://github.com/zpl1025"},{default:o(()=>[...n[12]||(n[12]=[t("zpl1025",-1)])]),_:1}),n[16]||(n[16]=t(" 校對：",-1)),i(s,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...n[13]||(n[13]=[t("Caroline",-1)])]),_:1})]),r("p",null,[n[19]||(n[19]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[17]||(n[17]=[t("LCTT",-1)])]),_:1}),n[20]||(n[20]=t(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:o(()=>[...n[18]||(n[18]=[t("Linux中國",-1)])]),_:1}),n[21]||(n[21]=t(" 榮譽推出",-1))])])}const P=a(g,[["render",x]]);export{f as __pageData,P as default};
